"""Reusable conversions for Meridian CRM legacy storage conventions."""

from datetime import date
from decimal import Decimal, ROUND_HALF_UP, localcontext


def to_iso(yyyymmdd: str | None) -> str | None:
    """Convert a legacy YYYYMMDD date to ISO format."""
    if yyyymmdd is None or yyyymmdd in ("", "00000000"):
        return None
    if (
        len(yyyymmdd) != 8
        or not yyyymmdd.isdigit()
    ):
        raise ValueError(f"invalid legacy date: {yyyymmdd!r}")

    parsed = date(
        int(yyyymmdd[0:4]),
        int(yyyymmdd[4:6]),
        int(yyyymmdd[6:8]),
    )
    return parsed.isoformat()


def from_iso(iso: str | None) -> str:
    """Convert an ISO date to legacy YYYYMMDD format."""
    if iso is None or iso == "":
        return "00000000"
    if (
        len(iso) != 10
        or iso[4] != "-"
        or iso[7] != "-"
        or not (iso[0:4] + iso[5:7] + iso[8:10]).isdigit()
    ):
        raise ValueError(f"invalid ISO date: {iso!r}")

    parsed = date.fromisoformat(iso)
    return parsed.strftime("%Y%m%d")


def yn(char: str | None) -> bool:
    """Convert a legacy Y/N value to bool, treating blank as N."""
    if char == "Y":
        return True
    if char is None or char in ("", "N"):
        return False
    raise ValueError(f"invalid legacy Y/N value: {char!r}")


def to_minor_units(amount, currency: str | None) -> int:
    """Convert a legacy decimal amount to currency minor units."""
    if amount is None or amount == "":
        return 0

    currency_code = "USD" if currency is None or currency == "" else currency
    exponent = 0 if currency_code == "JPY" else 2
    value = Decimal(str(amount))

    if not value.is_finite():
        raise ValueError(f"amount must be finite: {amount!r}")

    digits = len(value.as_tuple().digits)
    decimal_exponent = abs(value.as_tuple().exponent)
    with localcontext() as context:
        context.prec = max(28, digits + decimal_exponent + exponent + 4)
        scaled = value * (Decimal(10) ** exponent)
        rounded = scaled.to_integral_value(rounding=ROUND_HALF_UP)

    return int(rounded)
